*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_formKorNm1", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("formKorNm"))); } },
        { childId: "ipt_formKorNm2", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("formKorNm"))); } },
        { childId: "__rb1", fn: function () { return "전체 " + String(dma_formPage.get("total")) + "건 (" + String(dma_formPage.get("currentPage")) + "/" + String(dma_formPage.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

