/**
 * @method
 * @name scwin.viewFormList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.viewFormList = function () {
    /* sdd-asis-lifecycle:begin viewFormList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let all_checked = true;
    for (let i = 0; i < (document.editForm || { elements: [] }).editClass.length; i++) {
        if ((document.editForm || { elements: [] }).editClass[i].value === "TEMP") {
            continue;
        }
        const prefix = (document.editForm || { elements: [] }).editClass[i].value;
        if ((document.editForm || { elements: [] }).editClass[i].checked) {
            scwin.displaySubEditList(prefix, "block");
        } else {
            all_checked = false;
            scwin.displaySubEditList(prefix, "none");
        }
    }
    $c.util.getComponent("ipt_allEdit").setValue(all_checked);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.displaySubEditList
 * @author Inswave
 * @date 2026. 09. 29
 * @param prefix _display
 * @returns
 * @hidden N
*/
scwin.displaySubEditList = function (prefix, _display) {
    /* sdd-asis-lifecycle:begin displaySubEditList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const subobj = eval("document.all.subEditClass_" + prefix);
    for (let i = 0; i < subobj.length; i++) {
        subobj[i].style.display = _display;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.viewAllFormList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.viewAllFormList = function () {
    /* sdd-asis-lifecycle:begin viewAllFormList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < (document.editForm || { elements: [] }).editClass.length; i++) {
        (document.editForm || { elements: [] }).editClass[i].checked = $c.util.getComponent("dma_searchDisclosureFormReq").get("allEdit");
    }
    scwin.viewFormList();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openFormList
 * @author Inswave
 * @date 2026. 09. 29
 * @param subobj listseq
 * @returns
 * @hidden N
*/
scwin.openFormList = function (subobj, listseq) {
    /* sdd-asis-lifecycle:begin openFormList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formDiv = eval("document.all.formList_" + listseq);
    const blankDiv = eval("document.all.blankList_" + listseq);
    if (formDiv.style.display === "block") {
        subobj.src = "/img/submission/main/open_folder.gif";
        formDiv.style.display = "none";
        blankDiv.style.display = "block";
    } else {
        subobj.src = "/img/submission/main/close_folder.gif";
        formDiv.style.display = "block";
        blankDiv.style.display = "none";
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchDisclosureForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param searchScope
 * @returns
 * @hidden N
*/
scwin.searchDisclosureForm = async function (searchScope) {
    /* sdd-asis-lifecycle:begin searchDisclosureForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_searchDisclosureFormReq').set('searchScope', searchScope);
    $c.util.getComponent('dma_searchDisclosureFormReq').set('isAllEdit', "false");
    if (searchScope == 1) {
        if ($c.util.getComponent("dma_searchDisclosureFormReq").get("formKorNm1") === '') {
            await $c.win.alert('검색어를 입력 하세요');
            return;
        }
        for (let i = 0; i < (document.editForm || { elements: [] }).editClass.length; i++) {
            if ((document.editForm || { elements: [] }).editClass[i].checked) {
                break;
            }
            if (i === (document.editForm || { elements: [] }).editClass.length - 1) {
                $c.util.getComponent("dma_searchDisclosureFormReq").get("allEdit");
                $c.util.getComponent('dma_searchDisclosureFormReq').set('isAllEdit', "true");
            }
        }
    } else {
        if ($c.util.getComponent("dma_searchDisclosureFormReq").get("formKorNm2") === '') {
            await $c.win.alert('검색어를 입력 하세요');
            return;
        }
    }
    if ($c.util.getComponent("dma_searchDisclosureFormReq").get("allEdit") || searchScope == 2) {
        $c.util.getComponent('dma_searchDisclosureFormReq').set('isAllEdit', "true");
    }
    $c.util.getComponent('dma_searchDisclosureFormReq').set('formKorNm', $c.str.trim($c.util.getComponent(" document.editForm.formKorNm" + searchScope).getValue()));
    $c.util.getComponent('dma_searchDisclosureFormReq').set('tabDiv', "search");
    $c.util.getComponent('dma_searchDisclosureFormReq').set('method', "searchDisclosureForm");
    (document.editForm || { elements: [] }).action = "/submission/searchDisclosureForm.do";
    await scwin.tx_searchDisclosureForm();
    /* sdd-asis-lifecycle:end */
};


